 useEffect(()=>{if(!activeId){localStorage.removeItem('openclip-job');return;}localStorage.setItem('openclip-job',activeId);const es=new EventSource(`/api/jobs/${activeId}/events`);es.addEventListener('job',e=>{setJobs(old=>upsert(old,JSON.parse((e as MessageEvent).data)));setConnected(true);});es.onopen=()=>setConnected(true);es.onerror=()=>setConnected(false);return()=>es.close();},[activeId]);
 useEffect(()=>{if(!jobs.some(busy))return;const t=setInterval(()=>refresh().catch(()=>setConnected(false)),5000);return()=>clearInterval(t);},[jobs.some(busy)]);
