 function start(e?:React.FormEvent){e?.preventDefault();if(creating)return;try{localStorage.setItem('openclip-last-template',String(settings.editTemplate));}catch{/* remembering the style is optional */}if(file)upload(file);else if(url.trim())importLink();else setError('Paste a YouTube link or choose a video file first.');}
 async function importLink(){setCreating(true);setError('');try{const j=await api<Job>('/api/jobs',{method:'POST',body:JSON.stringify({url:url.trim(),options:settings})});setJobs(old=>upsert(old,j));select(j);}catch(e){setError((e as Error).message);}finally{setCreating(false);}}
